import math, random

def d(a,b):
    return math.sqrt(math.fsum((a[j]-b[j])**2 for j in range(len(a))))

def ref(X, k, max_iter):
    n=len(X)
    # init
    chosen=[0]; chosen_set={0}
    while len(chosen)<k:
        best=None; bestgap=None
        for i in range(n):
            if i in chosen_set: continue
            gap=min(d(X[i], X[c]) for c in chosen)
            if bestgap is None or gap>bestgap:
                bestgap=gap; best=i
        chosen.append(best); chosen_set.add(best)
    for _ in range(max_iter):
        labels=[]
        for i in range(n):
            bi=0; bd=None
            for cidx,c in enumerate(chosen):
                dd=d(X[i],X[c])
                if bd is None or dd<bd: bd=dd; bi=cidx
            labels.append(bi)
        new=[]
        for cidx in range(k):
            mem=[i for i in range(n) if labels[i]==cidx]
            if not mem:
                new.append(chosen[cidx]); continue
            bc=None; bcost=None
            for cand in mem:
                cost=math.fsum(d(X[cand],X[m]) for m in mem)
                if bcost is None or cost<bcost: bcost=cost; bc=cand
            new.append(bc)
        if new==chosen: break
        chosen=new
    labels=[]
    for i in range(n):
        bi=0; bd=None
        for cidx,c in enumerate(chosen):
            dd=d(X[i],X[c])
            if bd is None or dd<bd: bd=dd; bi=cidx
        labels.append(bi)
    return chosen, labels

import classicml
random.seed(1234)
mismatch=0
for trial in range(3000):
    n=random.randint(1,12)
    w=random.randint(1,3)
    k=random.randint(1,min(n,4))
    mi=random.randint(1,8)
    def cell():
        r=random.random()
        if r<0.5: return random.randint(-5,5)
        return round(random.uniform(-5,5),2)
    X=[[cell() for _ in range(w)] for _ in range(n)]
    m=classicml.KMedoids(n_clusters=k,max_iter=mi).fit(X)
    ri,rl=ref(X,k,mi)
    if m.medoid_indices_!=ri or m.predict(X)!=rl or m.fit_predict(X)!=rl:
        mismatch+=1
        print("MISMATCH", trial, X, k, mi, m.medoid_indices_, ri, m.predict(X), rl)
        if mismatch>5: break
print("done, mismatches:", mismatch)
